    LANGUAGE_WRAPPER = 'Let [primes] be {k} distinct primes, let [x_list] be {k} positive integers, and let [u_list] be {m} distinct positive integers. For each i in {1, 2, ..., m}, define N_i = ∏_{j=1}^{k} (primes[j])^(x_list[j] * u_list[i]). Determine the number of positive integers that divide at least {threshold_t} of the numbers N_1, N_2, ..., N_m but no more than {upper_r} of them.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose parameters
k = rng.randint(3, 5)
m = rng.randint(4, 6)
primes_pool = [2, 3, 5, 7, 11, 13, 17, 19]
primes = rng.sample(primes_pool, k)
primes.sort()
# Choose base exponents x_j ensuring nontrivial structure
while True:
    x_list = [rng.randint(1, 4) for _ in range(k)]
    # ensure not all ones and some weight to increase difficulty
    if sum(x_list) >= k + 1:
        break
# Choose distinct multipliers u_i
candidate_us = list(range(2, 13))
u_list = rng.sample(candidate_us, m)
u_list.sort()
# Choose thresholds
